inline uint64_t Attach(uint32_t part,char modelHash='a',char packHash='b'){
    mhm::Asset asset;asset.part=part;asset.model=part==MHM_HEAD?"pl/auto/head":"pl/auto/waist";asset.modelSha=std::string(64,modelHash);asset.packSha=std::string(64,packHash);asset.basis.resize(64);
    for(const char* id:{"A","B"}){mhm::Key key;strcpy_s(key.info.id,id);key.info.maximum=1;key.info.exclusive_group=part==MHM_HEAD?1u:0u;key.deltas.push_back({0,1,0,0});asset.keys.push_back(key);}uint64_t handle=0;
    if(Core().Attach(std::move(asset),handle)!=MHM_OK)throw std::runtime_error("automatic fixture attach");return handle;
}
